// Some portions generated by Codex

// Shared models for the metadata-only Explore page and its independent section responses.

const ROLE_SECTIONS = ['outgoing', 'incoming', 'predicate', 'graph'];
const VALUE_SECTIONS = ['types', 'superClasses', 'subClasses', 'properties', 'superProperties', 'subProperties',
    'domain', 'range', 'label', 'comment'];

/** In-memory test store implementing the same owned-window lifetime as a real section store. */
function createMemoryRowStore(rows) {
    return {
        rows,
        disposed: false,
        async read(start, count) { return this.rows.slice(start, start + count); },
        async readOwned(start, count) {
            const window = { rows: await this.read(start, count), release() { this.rows = []; } };
            return window;
        },
        async count() { return this.rows.length; },
        async dispose() { this.disposed = true; }
    };
}

function createExploreSection(key, overrides = {}) {
    const rows = overrides.rows || [];
    const totalRows = overrides.totalRows === undefined ? rows.length : overrides.totalRows;
    return {
        key,
        status: 'ready',
        countStatus: 'ready',
        count: String(totalRows),
        countError: '',
        error: '',
        rows,
        totalRows,
        start: 0,
        vars: ROLE_SECTIONS.includes(key) ? ['subject', 'predicate', 'object', 'context'] : ['value'],
        expanded: false,
        revision: 0,
        ...overrides
    };
}

function createExploreSections(overrides = {}) {
    return Object.fromEntries([...ROLE_SECTIONS, ...VALUE_SECTIONS].map(key =>
        [key, createExploreSection(key, overrides[key] || {})]));
}

function createExploreModel(overrides = {}) {
    const { sections, controller, exploreController, exploreSections, ...modelOverrides } = overrides;
    const defaults = {
        viewId: 'explore',
        vars: [],
        rows: [],
        rowStart: 0,
        rowCount: 0,
        rowTopSpacer: 0,
        rowBottomSpacer: 0,
        // The metadata request still uses the ordinary PageModel's empty initial row store. Explore section rows are
        // owned by their per-section caches and never come from this empty shell store.
        rowStore: {},
        namespaceMap: {},
        links: [],
        metadata: {
            resource: '<urn:example:resource>',
            'explore-resource': '<urn:example:resource>'
        }
    };
    return {
        ...defaults,
        ...modelOverrides,
        exploreSections: exploreSections || createExploreSections(sections),
        exploreController: {
            page() {},
            expand() {},
            retry() {},
            ...controller,
            ...exploreController
        }
    };
}

module.exports = {
    ROLE_SECTIONS,
    VALUE_SECTIONS,
    createMemoryRowStore,
    createExploreModel,
    createExploreSection,
    createExploreSections
};
